ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_any_9"] = {
{"s11_a01_dont_ask_about_the_van_022","any",2,"reg=civilian|tmp=seasoned|day=40,400|mood=calm|world=vehicle",{1,"You'll do fine - pull your shift, stay out of the big shed, and I'd leave the van alone",2,"What van?",1,"There you go, you're doing it already - don't ask about the van"}},
{"s11_a01_alive_in_october_023","any",3,"reg=civilian,family|tmp=seasoned|day=80,400|mood=grim",{1,"I want to say the thing once and then never say it again",2,"Go on then",1,"We are alive in October because a man did murder in August - that's it - I'm done",3,"Alright"}},
{"s11_a01_who_does_the_enforcing_024","any",4,"reg=civilian,family|tmp=seasoned|day=60,400|mood=grim",{1,"He's laid up with that leg, somebody's got to read the watch list",2,"You read it, Ada, you're the one wrote it",3,"I'll read it, I won't enforce it, somebody else does the enforcing",4,"And that's the part nobody wants, and that's how come we've got a Kemble",1,"Say that slower, I think you just named it"}},
{"s11_a01_box_wont_hold_him_025","any",2,"reg=civilian,family|tmp=seasoned|day=60,400|mood=warm",{1,"He hauled the Vessels woman's water up two flights every day she was down - every day",2,"I know he did",1,"You can't get a man like that in one box - I've tried it, box won't hold him"}},
{"s11_a01_prayed_for_him_026","any",2,"reg=rescue|tmp=seasoned|day=30,400|hour=4,11|mood=calm",{1,"I prayed for that man this morning, took me a while to mean it",2,"You get there?",1,"Partway, asked the Lord to make him gentle and keep him breathing - in that order"}},
{"s11_a01_my_name_in_pencil_027","any",3,"reg=civilian|tmp=seasoned|day=60,400|mood=fear|world=door",{1,"Somebody put a fifth name on the door list last night - in pencil",2,"Whose?",1,"Mine - in my hand? No, somebody wrote my name up there for me",3,"That's either the kindest thing anybody's done for you or it's a hook"}},
{"s11_a01_quarry_foreman_028","any",2,"reg=worker,family|tmp=seasoned|day=40,400|mood=calm",{1,"I worked under a foreman at the quarry just like him - Hollis Tharp",2,"Was he bad?",1,"He was safe, nobody lost a hand on his shift in nineteen years - also a son of a bitch",2,"So which one do you tell your kids about?",1,"Both, you tell 'em both or you ain't telling it"}},
{"s11_a01_he_asked_me_029","any",2,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=grim|world=fence",{1,"He asked me, asked, not told - said would I mind taking the back fence Sunday",2,"What'd you say?",1,"Said yes before he finished, then stood there feeling like I'd been robbed"}},
{"s11_a01_i_didnt_look_030","any",2,"reg=worker|tmp=seasoned|day=40,400|mood=fear",{1,"I fixed the hinge on the big shed and I never looked in, I want that on the record",2,"There ain't no record",1,"Then I'm making one, out loud, to you, I didn't look"}},
{"s11_a01_who_do_i_talk_to_031","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|mood=calm",{1,"Who do I talk to about stopping here?",2,"Kemble",3,"Ada first - Ada writes you down, then Kemble says yes or no",4,"And if he says no, Ada's still got your name wrote down",1,"That's not helping, Weldon",4,"It's accurate, though"}},
{"s11_a01_babies_in_a_sentence_032","any",2,"reg=family|tmp=seasoned|day=60,400|mood=angry|world=building",{1,"He told me a camp with kids in it defends itself better - said it like a fact",2,"Is it a fact?",1,"Probably, that's what I hate - he put our babies in a sentence about walls"}},
{"s11_a01_hat_off_door_shut_033","any",2,"reg=civilian,family|tmp=seasoned|day=60,400|mood=sad|world=vehicle,door",{1,"He sat out in that truck a long while after the Dossett boy - never come in for supper",2,"He eat anything?",1,"Ada took him a plate, said the door was shut and his hat was off - that's all she said"}},
{"s11_a01_three_days_in_it_034","any",2,"reg=civilian,worker|tmp=seasoned|day=80,400|mood=grim|world=building,rain",{1,"If he goes, this place has got about three days in it",2,"Three?",1,"Two if it rains, the wall don't hold a place together - he does, I hate saying it"}},
{"s11_a01_which_road_which_turns_035","any",3,"reg=civilian,family|tmp=seasoned|day=60,400|hour=4,11|mood=grim|world=road",{1,"The Rickards pulled out this morning, took the wagon and both goats",2,"Nobody stopped 'em?",1,"He stood at the gate and told 'em which road and which turns - then he shut it",3,"That was decent of him",1,"It was decent, I am tired of being surprised by it"}},
{"s11_a01_loretta_said_please_036","any",2,"reg=worker,civilian|tmp=seasoned|day=40,400|hour=4,11|mood=grim",{1,"Diesel come up out of the ground this morning, two drums of it",2,"So somebody said please",1,"Loretta said it, in front of everybody, looked him right in the face doing it",2,"What'd that cost her",1,"Don't know yet, neither does she"}},
{"s11_a01_who_comes_up_the_stairs_037","any",2,"reg=rescue|tmp=seasoned|day=30,400|mood=angry|world=stairs,building",{1,"He wants the wall men seen first, I see worst first, that's how it's done",2,"He ain't gonna argue medicine with you",1,"He won't argue, he'll just decide who gets up the stairs to me"}},
{"s11_a01_tree_would_apologize_038","any",3,"reg=worker,civilian|tmp=seasoned|day=60,400|mood=funny|world=trees",{1,"You reckon if a tree fell on Kemble the tree'd apologize?",2,"Hah - quit it",3,"Tree'd say it was aiming at somebody else",1,"There it is, alright, that's enough of that - back to work"}},
{"s11_a01_died_old_folks_brought_food_039","any",2,"reg=family|tmp=seasoned|day=60,400|mood=grim",{1,"Daddy's mine had a man like that in twenty-nine, kept the checks coming, broke a fella's jaw",2,"And what came of him?",1,"Nothing happened to him, died old in his bed, folks brought food to the house"}},
{"s11_a01_coffee_can_under_smokehouse_040","any",4,"reg=civilian,family|tmp=seasoned|day=80,400|mood=fear|world=vehicle,building",{1,"Somebody needs to write down what happened with that van, on paper, with dates",2,"Keep it where? He goes in every room in this house",3,"Bury it, coffee can under the smokehouse floor",4,"Y'all hear yourselves? Burying a paper about a man we eat supper with",1,"Yeah, we hear it - go get the can"}},
{"s11_a01_keep_your_boots_on_041","any",2,"reg=civilian|tmp=seasoned|day=40,400|mood=calm",{1,"Y'all got a fella runs this place?",2,"We got a fella",1,"Every place does now - is he the kind you can sleep near?",2,"You can sleep - keep your boots on"}},
{"s11_a01_came_out_in_his_voice_042","any",2,"reg=civilian,family|tmp=seasoned|day=60,400|mood=grim|world=building",{1,"He's got that line of his, the wall don't sleep",2,"Says it at every shift change",1,"I said it to my own kid yesterday - come right out of my mouth in his voice"}},
{"s11_a01_hole_he_dug_043","any",2,"reg=rescue|tmp=seasoned|day=40,400|mood=sad",{1,"He didn't come to the burying, first one he's missed",2,"Maybe he couldn't",1,"Maybe, or he won't stand at a hole he dug - I'd rather it was the first one"}},
{"s11_a01_never_the_same_watch_044","any",2,"reg=worker,civilian|tmp=seasoned|day=40,400|mood=calm",{1,"Notice he never puts me and Weldon on the same watch?",2,"Now you say it",1,"Two men that like each other will cover for each other - he knows the trade"}},
{"s11_a01_cowards_answer_045","any",2,"reg=family|tmp=seasoned|day=60,400|mood=sad|world=door",{1,"Bug asked me is Mr. Kemble a bad guy",2,"What did you say to her?",1,"Said he's the man that keeps the door locked, she said okay, went back to her cards",2,"That was a good answer",1,"That was a coward's answer and she'll work it out by fifteen"}},
{"s11_a01_you_weld_046","any",2,"reg=worker|tmp=seasoned|day=30,400|mood=calm",{1,"You weld?",2,"Some - stick, it ain't pretty",1,"Then you'll eat before I do, and that's how it goes here - don't feel bad - just eat"}},
{"s11_a01_i_aint_him_047","any",4,"reg=civilian,family|tmp=seasoned|day=80,400|mood=grim",{1,"Say we did it, say five of us stood up at once and said no more",2,"And then what",3,"Then somebody's holding that gate at two in the morning, and you look round, and it's him",4,"Unless it's you, Loretta",3,"I ain't him... which is a compliment and a problem both"}},
{"s11_a01_democratic_and_hungry_048","any",2,"reg=civilian|tmp=seasoned|day=60,400|mood=funny",{1,"That bunch over at Wickham's feed store's got no boss at all - they vote every little thing",2,"How they doing?",1,"Hungry, real democratic and real hungry"}},
{"s11_a01_room_looked_at_its_shoes_049","any",3,"reg=civilian,family|tmp=seasoned|day=60,400|mood=grim",{1,"Y'all think I want that list?",2,"Somebody's got to hold it",1,"I've asked twice for a volunteer, both times the room got real interested in its shoes",3,"I'll take it",1,"No you won't, Ada, you'd be fair, and we'd all starve fair"}},
{"s11_a01_said_my_mothers_name_050","any",2,"reg=civilian,family|tmp=seasoned|day=60,400|mood=warm",{1,"He come up and asked after my mother by her name - Verna, nobody's said it in two months",2,"He does that",1,"I know he does, still stood there with my eyes stinging over a man I don't trust"}},
{"s11_a01_besides_my_head_051","any",2,"reg=civilian,family|tmp=seasoned|day=80,400|mood=grim|world=vehicle",{1,"Three fellas off the van, the sick man in the yard, the Rickards' goats he kept back",2,"You're keeping a tally",1,"Somebody has to, not for a court - just so the number's somewhere besides my head"}},
{"s11_a01_pocket_is_buried_052","any",4,"reg=civilian,family|tmp=seasoned|day=200,400|mood=calm",{1,"Alright, he's in the ground, who reads the list",2,"There ain't a list, he carried it in his pocket and the pocket's buried",3,"Then we start a new one and we start it different",4,"Different how - say the how part, everybody stops at different",1,"Water first - kids first, nobody goes in that shed alone - that's three - write it down"}},
{"s11_a02_not_one_dog_001","any",3,"reg=civilian,family|tmp=seasoned|day=30,400|mood=fear",{1,"Hot water in the taps, kids riding bicycles round the square, laundry on the line",2,"So how come you're sat out here in the wet?",1,"Took me two days before it hit me, not one dog in that town - not a single one",3,"Huh",1,"Yeah, huh, walked out Sunday morning and I never asked a soul about it"}},
{"s11_a02_never_past_the_shed_002","any",2,"reg=civilian|tmp=seasoned|day=30,400|mood=grim",{1,"Showed us the garden, the water tank, the clinic, same route every single time",2,"Sounds alright to me",1,"Never once the shed at the end of that lane - went around it twice, I marked that"}},
{"s11_a02_carbon_under_it_003","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=fear",{1,"Wanted the count in my family - my trade, and who'd come hunting me if I turned up gone",2,"That last one",1,"On a clipboard, too, with a carbon sheet under it"}},
{"s11_a02_eleven_tickets_004","any",3,"reg=civilian,worker|tmp=seasoned|day=30,400|mood=grim",{1,"At that gate they kept your long gun, awful polite about it",2,"Did you get it back?",1,"They gave you a paper ticket. Mine read forty-one",3,"Forty-one tickets. How many folks had you seen in there?",1,"About thirty. Made me wonder who hadn't come back for theirs. Couldn't know just by subtracting"}},
{"s11_a02_sorts_beans_005","any",2,"reg=worker,civilian|tmp=seasoned|day=30,400|mood=calm|world=building",{1,"Bed don't cost you, food don't cost you, you pull your shift up on the wall, is all",2,"And a man with a bad back?",1,"Then he sorts beans in the church kitchen, everybody works or everybody walks"}},
{"s11_a02_already_coiled_006","any",2,"reg=civilian|tmp=seasoned|day=30,400|mood=fear|world=vehicle",{1,"I asked what come of them folks that had the blue van",2,"And?",1,"Fella got real busy coiling a hose that was already coiled - never did answer me"}},
{"s11_a02_hung_the_other_three_right_007","any",3,"reg=worker,civilian|tmp=seasoned|day=30,400|mood=grim|world=fence",{1,"That front gate swings inward, hinges set on the inside of the fence",2,"So?",1,"So you go ahead and ask yourself who they hung that gate for",3,"Maybe they just hung it wrong",1,"Maybe, they hung the other three right"}},
{"s11_a02_in_that_order_008","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=fear",{1,"Little girl give me the rules while her mama was fetching my bedding",2,"What rules?",1,"In the house by nine - stay out the back lot - don't speak to the man up the tower",2,"Which one did she say first?",1,"She said 'em in that order, kids don't shuffle a list, they say it how they learned it"}},
{"s11_a02_whole_price_009","any",3,"reg=family,civilian|tmp=seasoned|day=30,400|mood=grim|world=vehicle",{1,"They'll take every one of us, beds, meals, the doctor, all of it",2,"What do they want",1,"The truck, only thing they asked for - that's the price, start to finish",3,"Then it's a fair deal and I hate it"}},
{"s11_a02_two_at_the_culvert_010","any",4,"reg=civilian,family|tmp=seasoned|day=30,400|mood=calm|world=fence",{1,"Power's on in there, you can hear a freezer kick on from the fence",2,"Then we go",3,"We go, and we're stood inside their fence with our guns in a box",4,"Or we sit out here in the wet and be proud about it",1,"Two of us go in, two hold at the culvert till Thursday, that's the deal I'll take"}},
{"s11_a02_white_towel_signal_011","any",2,"reg=family,civilian|tmp=seasoned|day=30,400|mood=grim|world=window",{1,"If it's straight in there I'll hang a towel out the second window - white towel",2,"And if it ain't straight?",1,"Then there's no towel and you don't see me again - you do not come in after me"}},
{"s11_a02_wrote_that_one_twice_012","any",2,"reg=civilian,family|tmp=fresh,seasoned|day=30,400|mood=fear",{1,"Woman asked could I sew, I said some - she smiled like I'd passed a test",2,"You did pass a test",1,"Then she asked was I married, that one she wrote down twice"}},
{"s11_a02_actual_bacon_013","any",2,"reg=civilian,worker|tmp=seasoned|day=60,400|mood=grim",{1,"They had greens with bacon in 'em, actual bacon, and not the last of it either",2,"Where's a town get bacon this time of year?",1,"That's what I chewed on, and I do mean chewed - I cleaned the plate"}},
{"s11_a02_brass_still_bright_014","any",2,"reg=rescue,civilian|tmp=seasoned|day=30,400|mood=grim|world=door",{1,"Prettiest little church on that square - white steeple, padlock on the door",2,"A padlock, on a church",1,"New one, too, brass still bright on it"}},
{"s11_a02_said_it_to_my_shoes_015","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=fear",{1,"Asked a boy on the square did he like living there - he said yes sir",2,"Kids say yes sir",1,"He said it to my shoes, not to me, to my shoes"}},
{"s11_a02_talked_faster_016","any",2,"reg=civilian|tmp=seasoned|day=30,400|mood=grim",{1,"Fella showing us round never quit talking, not for a minute, the whole hour",2,"Friendly sort",1,"Friendly, and every time we come near that lane by the tank, he talked faster"}},
{"s11_a02_would_not_look_at_us_017","any",2,"reg=civilian,family|tmp=seasoned|day=60,400|mood=fear",{1,"There's a Rosewood couple been inside since September, they wouldn't look at us",2,"Scared?",1,"Fed, clean clothes, wouldn't look at us - you tell me which one that is"}},
{"s11_a02_who_decides_who_hurts_018","any",2,"reg=rescue|tmp=seasoned|day=30,400|mood=grim",{1,"Their clinic's got a drug cabinet with a lock on it and a man sat by the lock",2,"That's sensible",1,"It's sensible, it's also somebody choosing who hurts - I'd like a name for that somebody"}},
{"s11_a02_say_your_piece_019","any",4,"reg=civilian,family|tmp=seasoned|day=30,400|mood=angry|world=building",{1,"Alright - Verdict",2,"Good water, good wall - good food, doctor on the square",3,"And a shed they walk you around, and eleven gun tickets nobody's claimed",4,"Y'all are fixing to talk us out of a warm room over a shed",1,"We might - say your piece, Junior, then we'll do hands"}},
{"s11_a02_fact_said_friendly_020","any",3,"reg=civilian|tmp=seasoned|day=30,400|mood=fear",{1,"Told the man at the gate we'd think on it and come back Friday",2,"What'd he say to that?",1,"Said that's fine, said folks that think on it mostly don't come back - then he smiled",3,"That's a threat",1,"That's a fact said friendly, which I'd call worse"}},
{"s11_a02_stack_on_the_curve_021","any",2,"reg=worker,civilian|tmp=seasoned|day=30,400|mood=grim|world=vehicle,road",{1,"Two mile of road up to that gate and not one dead car sat on it",2,"They cleared it, good for them",1,"They cleared it and they stacked 'em, and the stack's on the outside of the curve",2,"Huh, so you come round that curve and you can't turn a truck around",1,"Not a truck, not a car, not a bicycle, hardly"}},
{"s11_a02_somebodys_got_paint_022","any",2,"reg=civilian|tmp=seasoned|day=30,400|mood=calm",{1,"Sign at the turnoff reads Families Welcome, Inquire At Gate",2,"Hand painted?",1,"Painted neat, somebody took their time on it - somebody's got paint"}},
{"s11_a02_offered_my_wife_nothing_023","any",2,"reg=worker,family|tmp=seasoned|day=30,400|mood=angry|world=door",{1,"Soon as I said pipefitter, that whole room turned around on me",2,"Good turn?",1,"They offered me a house, a house, with a door that locks from the inside",2,"Take it",1,"They offered my wife nothing, just me and the house - so, no"}},
{"s11_a02_till_they_know_you_024","any",2,"reg=family|tmp=seasoned|day=30,400|mood=fear",{1,"Men bunk in the school, women and kids over in the Methodist annex",2,"For how long?",1,"Till they know you, the man said, asked him how long that takes and he changed the subject"}},
{"s11_a02_nobody_in_the_yards_025","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=fear",{1,"Wash hung on every line in that town, shirts, sheets, kids' overalls",2,"Means water and soap, that's a lot",1,"Means that, also means nobody out in the yards - all them lines and nobody hanging"}},
{"s11_a02_ran_the_school_board_026","any",2,"reg=civilian,worker|tmp=seasoned|day=30,400|mood=grim",{1,"They call him the administrator - not mayor - not boss - administrator",2,"What was he before?",1,"Ran the school board, he says, and he says it like it settles something"}},
{"s11_a02_glass_of_cold_milk_027","any",2,"reg=family|tmp=seasoned|day=30,400|mood=sad",{1,"Wesley cried when we walked out, first he's cried since Riverside",2,"He had a bed for one night",1,"A bed, cold milk, a girl his own age - that's what I took off him",2,"You took him out of a place we don't understand yet",1,"You go tell him that - I tried - he's eight"}},
{"s11_a02_alive_to_be_sorry_028","any",4,"reg=civilian,family|tmp=seasoned|day=30,400|mood=angry",{1,"And if we're wrong? If it's just a town that's got itself together?",2,"Then we walked off from beds",3,"Then we walked off from beds and we're alive to be sorry about it",4,"That's a thing folks say right before they're wrong",1,"It is - fine, somebody rides back in ten days and looks again - not me"}},
{"s11_a02_name_in_the_prayer_029","any",2,"reg=civilian,rescue|tmp=seasoned|day=30,400|mood=fear",{1,"I'd have stayed, I was going to stay, I had my bag off my shoulder",2,"What turned you?",1,"Woman said grace and she put his name in it - right between the Lord's and amen"}},
{"s11_a02_looking_down_at_the_square_030","any",2,"reg=civilian,worker|tmp=seasoned|day=30,400|mood=grim|world=stairs",{1,"Man up that water tower with a rifle, day and night, two shifts",2,"That's a watch, we'd do the same thing",1,"Ours would face out, that ladder's inside the fence and he was looking down at the square"}},
{"s11_a02_then_he_had_two_031","any",2,"reg=rescue|tmp=seasoned|day=30,400|mood=grim",{1,"The administrator asked would I preach Sunday, said folks needed it bad",2,"That's a good sign, ain't it",1,"He also asked what I'd preach on, then he had a suggestion - then he had two"}},
{"s11_a02_somebodys_mowing_them_032","any",2,"reg=civilian|tmp=seasoned|day=30,400|mood=fear|world=window",{1,"Forty houses in that town, I counted thirty-one people in two days of looking",2,"Some folks stay inside",1,"Nine houses with the curtains pulled and the grass cut short - somebody's mowing 'em"}},
{"s11_a02_eleven_minutes_033","any",3,"reg=civilian,worker|tmp=seasoned|day=30,400|mood=grim",{1,"Getting in was easy, real easy, should've told me something",2,"How hard was getting out?",1,"Man at the gate had to go ask, walked off, asked, walked back - eleven minutes",3,"You timed it?",1,"I had a watch and nothing else to do, eleven minutes to let a man leave"}},
{"s11_a02_woman_named_della_034","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=warm",{1,"Y'all keep on about that town, I stopped at one that was straight",2,"Where at",1,"Little place past Ekron - ten families - give me supper, let me sleep in the barn",2,"And what'd they want off you?",1,"Wanted to know had I seen a woman named Della - that was it - whole ask"}},
{"s11_a02_he_can_hear_you_035","any",4,"reg=family|tmp=seasoned|day=30,400|mood=angry",{1,"They'll take the group, all of it - except Papaw",2,"Except Papaw",3,"Said they can't feed a mouth that can't work, said it real kind, too",4,"Then they can't feed us neither, 'cause we ain't splitting up",1,"Say that in front of him, go on, he's sat right there and he can hear you"}},
{"s11_a02_what_else_has_he_done_036","any",2,"reg=worker,civilian|tmp=seasoned|day=30,400|mood=grim",{1,"Four on, eight off, three shifts, and nobody sleeps on post",2,"That's real soldiering",1,"That's a man who's done it before, makes me wonder what else he's done before"}},
{"s11_a02_forty_men_and_time_037","any",2,"reg=worker|tmp=seasoned|day=30,400|mood=calm|world=cars,fence,road",{1,"Chain link, then a line of cars, then hog panel - three deep on the road side",2,"Somebody there knows fence",1,"A fence like that just means somebody had time, tools and forty men"}},
{"s11_a02_same_handwriting_both_038","any",2,"reg=civilian,family|tmp=seasoned|day=60,400|mood=fear",{1,"Delia went in, back in October, I've had word off her twice, both times by a trader",2,"What'd she say?",1,"First time, come join me, second time, don't come, same handwriting on both"}},
{"s11_a02_say_it_back_to_me_039","any",2,"reg=family|tmp=seasoned|day=30,400|mood=fear",{1,"I'll go in by myself and look, y'all hold at the Kelso place three days",2,"And if you don't come out?",1,"You don't come after me, you go to Riverside and find Aunt Cleo - say it back",2,"Riverside - Aunt Cleo - three days",1,"Three days and then you go - don't you dare come through that gate"}},
{"s11_a02_bowl_of_sugar_040","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=grim",{1,"They set a bowl of sugar on the table - sugar, just sat there in the middle",2,"For the coffee",1,"For watching who takes too much, I took one spoon and I wanted six"}},
{"s11_a02_week_is_all_it_took_041","any",2,"reg=civilian|tmp=seasoned|day=30,400|mood=fear",{1,"Man in the next bunk's been in a week and he already talks like them",2,"Talks like them how?",1,"Starts near every sentence with what the administrator says - one week, that's all it took"}},
{"s11_a02_walked_them_fields_042","any",2,"reg=civilian,worker|tmp=seasoned|day=30,400|mood=fear|world=door",{1,"Boarding kennel on the edge of that town - twelve runs, doors stood open",2,"Somebody turned 'em loose",1,"Then they'd be out in them fields, I walked them fields, no dogs, no mess, no smell"}},
{"s11_a02_write_down_who_goes_043","any",4,"reg=civilian,family|tmp=seasoned|day=30,400|mood=calm",{1,"We're sending one person in to look - so - who",2,"Me, ain't nobody waiting on me",3,"That's just why it can't be you, nobody to notice you never come back",4,"Send two, and make it a married pair, 'cause that's what they take first",1,"Hands for sending two, and somebody write down who goes and what day"}},
{"s11_a02_show_me_your_hands_044","any",2,"reg=rescue,civilian|tmp=seasoned,veteran|day=20,400|mood=grim",{1,"Hold it right there, don't come no closer to that wire",2,"We ain't armed, we got a kid with us, he's asleep on my back",1,"Show me your hands, both of 'em - how many with you?",2,"Four, my wife, my boy, my sister",1,"Anybody hurt? Anybody bit? Lay the long gun down and step off of it"}},
{"s11_a02_say_your_wifes_name_045","any",2,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=warm",{1,"That you, Weldon?",2,"It's me - get that light out of my eyes",1,"Say your wife's name",2,"Odessa, same as Tuesday, same as it'll be Thursday",1,"Come on in, rules are rules, and you wrote half of 'em"}},
{"s11_a02_peppermint_in_his_pocket_046","any",2,"reg=family,civilian|tmp=seasoned|day=30,400|mood=warm",{1,"He gave my girl a peppermint out of his shirt pocket - had it there ready",2,"Ready",1,"A man don't carry candy for himself, he carries it for somebody else's kid"}},
{"s11_a02_used_my_name_first_047","any",2,"reg=civilian|tmp=seasoned|day=30,400|mood=fear",{1,"Man at that gate used my name before I ever gave it him",2,"Somebody told him",1,"Somebody did, and whoever it was knew where we been camping, too"}},
{"s11_a02_no_sixteen_though_048","any",2,"reg=rescue,civilian|tmp=seasoned|day=40,400|mood=fear",{1,"Little graveyard behind that church, old stones, and eleven new ones",2,"Eleven's a lot for a town that size - they got names on 'em?",1,"Numbers - painted on, nine up through nineteen, no sixteen, though"}},
{"s11_a02_somebody_elses_tanker_049","any",2,"reg=worker|tmp=seasoned|day=40,400|mood=grim",{1,"They got a backhoe running in there, fresh filter on it, running like a top",2,"Who's got diesel to burn this late in the year?",1,"Whoever's got a tanker, or whoever's got somebody else's tanker"}},
{"s11_a02_ate_the_eggs_on_the_road_050","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=funny|world=road",{1,"We told 'em no and they packed us a sack anyhow - bread, half a ham, four boiled eggs",2,"Well, that's kindness",1,"That's kindness or that's advertising, either road, we ate the eggs by dinnertime"}},
{"s11_a02_leave_the_keys_where_i_can_reach_051","any",2,"reg=family|tmp=seasoned|day=30,400|mood=grim|world=vehicle,fence",{1,"I ain't going in there",2,"Papaw, they've got a doctor and a bed with springs in it",1,"I been inside a fence once before, in Korea, on the good side of the wire - no",2,"Alright",1,"Alright, you go on if you want - leave the truck keys where I can reach 'em"}},
{"s11_a02_not_today_but_i_will_052","any",4,"reg=civilian,family|tmp=seasoned|day=60,400|hour=4,11|mood=sad",{1,"Ottie come out of that town this morning, walked up the lane by herself",2,"She alright?",3,"She's thin and she's got all her teeth and she won't say a word about it",4,"Then don't ask her, feed her and let her sit and let her be",1,"I'm gonna ask her - not today, but I am gonna ask her"}},
{"s11_a03_nobody_eats_nine_cans_001","any",3,"reg=civilian,family|tmp=seasoned|day=30,400|hour=4,11|mood=angry|world=building",{1,"Forty-one cans Tuesday morning, thirty-six this morning",2,"Maybe you miscounted Tuesday",1,"I count twice - always have, and nobody in this house eats nine cans",3,"So somebody's carrying",1,"Somebody's carrying, I ain't saying who and I ain't looking at anybody"}},
{"s11_a03_argue_with_the_door_002","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=calm|world=door",{1,"Kids eat first, then whoever pulled watch - then the rest of us",2,"That puts me last three days running",1,"It does, I wrote it on the door so you'd argue with the door and not with me"}},
{"s11_a03_forty_puffs_003","any",3,"reg=rescue,civilian|tmp=seasoned|day=30,400|mood=grim",{1,"One inhaler, maybe forty puffs in it, and two people that need it",2,"One of 'em's a child",1,"One's a child and one's the man that keeps our water clean - you want a vote?",3,"No",1,"Me neither, somebody decides by Friday and it's going to be me"}},
{"s11_a03_watched_the_boy_go_hungry_004","any",3,"reg=civilian,family|tmp=seasoned|day=40,400|mood=angry",{1,"Found candy bars rolled in Junior's bedroll, six, and a tin of sardines",2,"Well, hell",1,"Stealing ain't the part, he set there and watched the Tandy boy go hungry a solid week",3,"So what do we do",1,"I don't know, that's why I said it out loud in front of three people"}},
{"s11_a03_then_he_lifts_005","any",2,"reg=worker,civilian|tmp=seasoned|day=30,400|mood=grim",{1,"You fix a well pump? Pull a calf? Then you eat, and you eat good",2,"And if all a man can do is lift?",1,"Then he lifts, there's plenty to lift - I'm sorry, that's how it runs now"}},
{"s11_a03_food_aint_the_problem_006","any",2,"reg=worker,family|tmp=seasoned|day=30,400|mood=angry|world=inside,water,rain",{1,"I remember people counting cans while the creek got low and the well went gritty",2,"They thought having food was enough?",1,"They kept saying, we've got food. Like that answered what we'd drink"}},
{"s11_a03_arithmetic_with_me_007","any",2,"reg=civilian,family|tmp=seasoned|day=20,120|mood=grim",{1,"Ninety-five in the shade and here I am on about January",2,"Nobody wants to hear it in July",1,"Somebody's got to say it, sixteen people, four months of cold, do that sum with me"}},
{"s11_a03_watched_his_face_008","any",2,"reg=worker,civilian|tmp=seasoned|day=40,400|mood=angry",{1,"He called it twenty pound of flour - it's fourteen, weighed it on the feed scale",2,"He mis-sacked it, maybe",1,"He knew it was fourteen when he shook my hand - I watched his face while he done it"}},
{"s11_a03_full_bellies_take_it_better_009","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|mood=grim",{1,"Run come back with two sacks and a case of green beans - that's everything he brought back",2,"So what gets cut",3,"Coffee goes first, I'll take the cussing for it",4,"Cut coffee and your watch is asleep by four in the morning - cut something else",1,"Then name it, out loud, in front of everybody, same as he did"}},
{"s11_a03_tell_me_days_010","any",2,"reg=civilian,worker|tmp=seasoned|day=30,400|mood=calm",{1,"Quit telling me cans - tell me days",2,"Nine days, eleven if nobody works hard",1,"Nine days - hear how different that sits in your mouth than sixty-two cans?"}},
{"s11_a03_gallon_a_head_011","any",2,"reg=worker,family|tmp=seasoned|day=30,400|mood=calm|world=water",{1,"Gallon a head a day just for drinking - sixteen head, that's sixteen gallon hauled",2,"And washing?",1,"Washing's a want, the garden ain't, I'll wash in the creek and be happy"}},
{"s11_a03_take_it_off_yours_012","any",2,"reg=family|tmp=seasoned|day=30,400|mood=angry",{1,"I remember you giving Callie a grown woman's plate",2,"She was growing",1,"The whole table watched. You knew they would",2,"I'd have taken it off mine",1,"I know. You wanted them to see somebody choosing that, not just hear a rule"}},
{"s11_a03_nell_eats_twice_013","any",2,"reg=family,rescue|tmp=seasoned|day=30,400|mood=calm",{1,"Nell eats twice, morning and evening, full plate both",2,"Nobody's arguing that",1,"Somebody will in six weeks when it's beans, so I'm saying it now while it's easy"}},
{"s11_a03_lids_is_the_trouble_014","any",2,"reg=worker,family|tmp=seasoned|day=40,300|mood=calm",{1,"Two hundred foot of green beans and a hard freeze the second week of October",2,"So we can everything",1,"We can everything, and that's jars, lids and a fire three days - lids is the trouble"}},
{"s11_a03_honest_about_it_015","any",2,"reg=rescue,civilian|tmp=seasoned|day=30,400|mood=grim",{1,"Half a can of beans is half a day's eating if you're honest about it",2,"Nobody's honest about it",1,"No, everybody calls a can a meal, 'cause the truth means somebody don't eat"}},
{"s11_a03_even_a_box_of_matches_016","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=calm",{1,"Everything goes in the book, who took it, what it was, what day",2,"Even a box of matches?",1,"Even matches, not 'cause I care - so the day we're fighting, there's nothing to fight about"}},
{"s11_a03_try_another_one_017","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|hour=20,5|mood=angry|world=building",{1,"Book says somebody took two pound of lard Thursday and never signed for it",2,"Might've been me, I don't sign every single time",3,"And that right there is the whole problem",4,"Or Ada wrote it down wrong, she's seventy-one and it's dark in that pantry",1,"She's seventy-one and she ran the cannery office twenty-two years - try another one"}},
{"s11_a03_not_a_seasoning_problem_018","any",2,"reg=worker,family|tmp=seasoned|day=40,400|mood=grim",{1,"Salt, nobody thought about salt and now everybody's thinking about salt",2,"How much have we got?",1,"Box and a half, salt's how you keep meat, so that ain't a seasoning problem"}},
{"s11_a03_part_thatll_spread_019","any",2,"reg=civilian,family|tmp=seasoned|day=40,400|mood=grim",{1,"I smelled meat cooking out back of the milk house last night, late",2,"Rabbit, probably, somebody snared a rabbit",1,"Somebody snared a rabbit and ate it by himself, that's the part that'll spread"}},
{"s11_a03_like_its_one_number_020","any",2,"reg=worker,civilian|tmp=seasoned|day=30,400|mood=calm",{1,"Head count's nineteen, mouths that can't work, six - four kids and two old",2,"So thirteen working",1,"Thirteen working, nineteen eating, and we say nineteen like it's one number"}},
{"s11_a03_thats_on_us_021","any",2,"reg=family|tmp=seasoned|day=30,400|mood=sad",{1,"Wesley put half his bread back in the pan and said he weren't hungry",2,"He was hungry",1,"He was starved, he heard us at this table Tuesday night, that's on us, not him"}},
{"s11_a03_she_would_have_sent_cornbread_022","any",2,"reg=family|tmp=seasoned|day=30,400|mood=warm",{1,"Mrs. Tandy sent over half a pone of cornbread, I about handed it back to her",2,"Don't you dare",1,"I know, my mother'd have died before she took charity off a neighbor",2,"Your mother'd have sent the cornbread, and she'd have wanted it eat"}},
{"s11_a03_whole_prize_023","any",2,"reg=rescue|tmp=seasoned|day=30,400|mood=calm",{1,"Sick eat more and work less, that's how it has to run",2,"And them that don't get sick?",1,"They get to not be sick, that's the prize, and it's a good one"}},
{"s11_a03_shaking_their_hands_024","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=grim|world=road",{1,"Two more come in off the road today, that's twenty-one now",2,"Twenty-one at nine days makes it seven days",1,"Yeah, I worked that in my head while I was shaking their hands and smiling"}},
{"s11_a03_say_the_second_half_again_025","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|mood=grim|world=fence",{1,"There's a family stood at the fence, four of 'em and one's a baby",2,"We're at seven days of food",3,"Then we're at six with them, six days and a baby",4,"Or we're at seven days and we're the kind of folks that done that",1,"Say the second half again, Dovie - slower, then we'll do hands"}},
{"s11_a03_needle_where_both_can_see_026","any",2,"reg=worker,civilian|tmp=seasoned|day=40,400|mood=calm|world=vehicle",{1,"Bring the scale, set it on the tailgate where both sides can see the needle",2,"That's calling the man a liar before he opens his mouth",1,"It's calling everybody honest in advance, comes out cheaper that way"}},
{"s11_a03_coffee_for_lids_027","any",2,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=calm",{1,"Half a pound of coffee bought us eight dozen canning lids",2,"Coffee for lids",1,"Coffee's a want, lids is a winter - you take that trade every time it's offered"}},
{"s11_a03_two_keys_two_locks_028","any",3,"reg=civilian,family|tmp=seasoned|day=40,400|hour=16,5|mood=calm",{1,"Who's got the pantry key tonight",2,"Whoever's on watch, same as always",1,"From here out it's two keys and two locks, and both people there to open it",3,"That's a pile of trouble for a room full of beans",1,"It's trouble that saves a friendship - go find me another hasp"}},
{"s11_a03_rich_and_stupid_029","any",2,"reg=worker,family|tmp=seasoned|day=60,400|mood=funny",{1,"Hogs are hanging, we've got salt for one and we've got two hogs",2,"So one gets eat now",1,"One gets eat this week and every soul here is gonna feel rich and stupid about it"}},
{"s11_a03_shes_remembering_030","any",3,"reg=family,civilian|tmp=seasoned|day=40,400|mood=warm",{1,"Found a flour sack of pintos pushed under Mamaw Tandy's bed",2,"Hoarding",1,"She's eighty-four, she come up in the thirties - she ain't hoarding, she's remembering",3,"So what'd you do about it?",1,"Left it there, set a can of peaches in beside it and never said a word"}},
{"s11_a03_dog_eats_what_i_eat_031","any",3,"reg=family,civilian|tmp=seasoned|day=40,400|mood=warm",{1,"Buck's been living on scraps, there ain't no scraps no more",2,"So what, we shoot the dog?",1,"Nobody said shoot the dog, I said there's no scraps, I'm asking what we do",3,"Dog earns his keep, he barked before any of us heard 'em Tuesday",1,"Then the dog eats what I eat and I'll take less - done - what's next"}},
{"s11_a03_nobody_gets_two_portions_032","any",4,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=angry|world=door,building,inside",{1,"Men on the wall should eat more, we're the ones out there carrying it",2,"Men on the wall do eat more, it's wrote on the door",3,"Not enough more, I've come in two notches on my belt since the fourth",4,"So has the woman doing the wash, and she ain't in here asking",1,"Half a cup more for wall shifts, nobody takes two portions, that's the ruling"}},
{"s11_a03_whose_cup_033","any",2,"reg=family,civilian|tmp=seasoned|day=30,400|mood=funny",{1,"Cup and a half of cornmeal a head - whose cup?",2,"The one hanging on the nail",1,"Then hang it back on the nail, 'cause yesterday somebody measured with a coffee mug"}},
{"s11_a03_two_toes_and_a_tail_034","any",2,"reg=worker,family|tmp=seasoned|day=40,400|mood=funny",{1,"Somebody's been in them beans",2,"Somebody with two toes and a tail - it's deer - look at the tracks",1,"Huh, best news I've had all month and I still lost the beans"}},
{"s11_a03_smart_man_his_daddy_035","any",2,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=calm",{1,"The Sowder boy trades honest, and he's fourteen years old",2,"Fourteen and honest",1,"Sends him 'cause nobody shoots a kid and nobody argues a kid down - smart man, his daddy"}},
{"s11_a03_but_it_has_the_habit_036","any",2,"reg=rescue|tmp=seasoned|day=30,400|mood=warm|world=building",{1,"That pantry at Cedar Grove fed forty families in eighty-nine when the plant shut",2,"And now?",1,"Now it's a card table, a hymn box and one can of pumpkin - but it's got the habit"}},
{"s11_a03_eats_more_than_the_sugar_037","any",2,"reg=civilian,family|tmp=seasoned|day=40,400|mood=funny",{1,"Things we cut, in order - coffee - sugar, then anybody's bad manners about it",2,"That last one ain't food",1,"Eats more than the sugar does"}},
{"s11_a03_beat_us_by_a_week_038","any",4,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=grim",{1,"Sav Rite's stripped, shelves, back room, loading dock - somebody beat us by a week",2,"Beat us by who?",3,"Whoever's got that backhoe running, is my guess",4,"So it's Friday cuts and no run Monday - say it plain to the house",1,"I'll say it after supper, bad news goes down easier on a full belly, that's just how it is"}},
{"s11_a03_its_his_rice_039","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=grim",{1,"Fella come in the gate with forty pound of rice on his back",2,"Then he's welcome",1,"It's his rice, that's what nobody's saying - his rice, and he's reading our book"}},
{"s11_a03_so_the_corn_knows_040","any",2,"reg=worker,family|tmp=seasoned|day=40,300|mood=funny",{1,"Somebody sits in that corn dark to light, every night, till it's picked",2,"Sits there doing what, exactly?",1,"Sitting, that's the job - you sit in the corn so the corn knows somebody's there"}},
{"s11_a03_holding_em_out_at_me_041","any",2,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=funny",{1,"Wickham's will take eggs, liquor, twenty-two shells and shoes, they won't take cash",2,"Nobody takes cash",1,"Fella tried to pay me in twenties last month, stood there holding 'em out at me"}},
{"s11_a03_sunday_its_a_cake_042","any",2,"reg=family|tmp=seasoned|day=40,400|mood=warm",{1,"It's Bug's birthday Sunday, she's asking for a cake",2,"We've got no eggs to spare and no sugar at all",1,"I know what we've not got, I'm asking what we have got",2,"Cornmeal, a little lard, jar of blackberry off your mother",1,"Then that's a cake - don't tell me it ain't - Sunday, that is a cake"}},
{"s11_a03_beans_in_a_jar_043","any",2,"reg=rescue,family|tmp=seasoned|day=60,400|mood=grim",{1,"Everybody's gums are going soft, that ain't a mystery - that's no greens",2,"We've got greens out there right now",1,"In October we do, it's the cold months, somebody start sprouting beans in a jar"}},
{"s11_a03_list_of_the_polite_044","any",2,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=angry|world=fence",{1,"I've asked you four times to sign that book",2,"I been here since June, I put this fence up with my hands",1,"I know you did - sign it anyway, else the book's just a list of the polite"}},
{"s11_a03_three_answers_by_dark_045","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|mood=grim",{1,"Fair and fed ain't the same thing - pick one and say which out loud",2,"Fed",3,"Fair",4,"Fed, then fair after, fair don't carry anybody through February",1,"That's three answers and I've got to have one by dark - y'all are a big help"}},
{"s11_a03_then_i_thought_about_february_046","any",2,"reg=worker|tmp=seasoned|day=40,400|mood=sad|world=door",{1,"Rats got in the cornmeal, two sacks ruined, and I'm the one left that door open",2,"You're telling me instead of hiding it",1,"I thought about hiding it, all morning I thought about it - then I thought about February"}},
{"s11_a03_id_rather_walk_full_047","any",3,"reg=family,worker|tmp=seasoned|day=60,400|mood=grim|world=vehicle",{1,"Man at Wickham's will give six sacks of feed corn for the Ford",2,"Six sacks for a running truck?",1,"A running truck with no gas and no gas coming - six sacks is a month of eating",3,"And then we're walking",1,"Then we're walking and eating, I'd rather walk full"}},
}
